@Test
void testUnregister_concurrentStateTransition_synchronized() throws Exception {
    coordinator.register(component);
    coordinator.start();

    var unregisterStarted = new CountDownLatch(1);
    var stateChangeReady = new CountDownLatch(1);

    // Thread A: unregister() - will pause after state check
    var unregisterFuture = executor.submit(() -> {
        // Hook to pause unregister mid-execution (requires test seam)
        coordinator.unregister(component.name());
    });

    // Thread B: start component to change state
    var startFuture = executor.submit(() -> {
        stateChangeReady.await();
        component.start().join();  // Transition STOPPED→RUNNING
    });

    unregisterStarted.countDown();
    stateChangeReady.countDown();

    // Expected: unregister() should either:
    // 1. Complete before start() (component removed while STOPPED) - OK
    // 2. Throw exception if state changed to RUNNING during check - OK
    // 3. NEVER remove RUNNING component silently - BAD

    // Validation: Check component not in inconsistent state
    assertFalse(
        component.getState() == RUNNING && coordinator.getState(component.name()) == null,
        "Component RUNNING but removed from coordinator"
    );
}
```

