## Core Mechanism

### BucketScheduler.java

```java
public class BucketScheduler<ID extends EntityID, Content> {
    private static final long BUCKET_DURATION_MS = 100;
    private static final long TIMEOUT_MS = 200;

    private final SimulationNode<ID, Content> node;
    private final CausalRollback<ID, Content> rollback;
    private final BucketBarrier barrier;
    private long currentBucket = 0;

    public void advanceBucket() {
        // 1. Checkpoint for potential rollback
        rollback.checkpoint(currentBucket, node.snapshotLocalStates());

        // 2. Wait for neighbors (with timeout)
        var outcome = barrier.waitForNeighborsReady(currentBucket, TIMEOUT_MS);
        if (outcome.result() == WaitResult.TIMEOUT) {
            handleTimeout(outcome.missingNeighbors());
        }

        // 3. Apply ghost updates (sorted by source rank for consistency)
        applyReceivedGhosts();

        // 4. Process physics (entities sorted by ID)
        processPhysics(getSortedEntities());

        // 5. Send ghost updates to neighbors
        sendGhostUpdates(currentBucket);

        // 6. Advance
        currentBucket++;
    }
}
```

### CausalRollback.java

```java
public class CausalRollback<ID extends EntityID, Content> {
    private static final int MAX_ROLLBACK_BUCKETS = 2;  // 200ms window

    private final Deque<Checkpoint<ID, Content>> checkpoints = new ArrayDeque<>();

    public record Checkpoint<ID, Content>(
        long bucket,
        Map<ID, EntityState<Content>> states,
        Set<UUID> processedMigrations
    ) {}

    public void checkpoint(long bucket, Map<ID, EntityState<Content>> states) {
        checkpoints.addLast(new Checkpoint<>(bucket, Map.copyOf(states), Set.of()));
        while (checkpoints.size() > MAX_ROLLBACK_BUCKETS + 1) {
            checkpoints.removeFirst();
        }
    }

    public boolean rollbackIfNeeded(long messageBucket, SimulationNode<ID, Content> node) {
        long currentBucket = node.getCurrentBucket();

        // Message too old - accept divergence
        if (messageBucket < currentBucket - MAX_ROLLBACK_BUCKETS) {
            log.warn("Message bucket {} too old, accepting divergence", messageBucket);
            return false;
        }

        // Find and restore checkpoint
        var checkpoint = findCheckpoint(messageBucket);
        if (checkpoint != null) {
            node.restoreState(checkpoint.states());
            node.setCurrentBucket(checkpoint.bucket());
            return true;
        }
        return false;
    }
}
```

### BucketBarrier.java

```java
public class BucketBarrier {
    private final Set<Integer> neighborRanks;
    private final Map<Integer, Long> neighborBuckets = new ConcurrentHashMap<>();

    public enum WaitResult { ALL_READY, TIMEOUT, PARTIAL }

    public record WaitOutcome(WaitResult result, Set<Integer> missingNeighbors, long waitTimeMs) {}

    public WaitOutcome waitForNeighborsReady(long bucket, long timeoutMs) {
        long deadline = System.currentTimeMillis() + timeoutMs;
        Set<Integer> missing = new HashSet<>(neighborRanks);

        while (!missing.isEmpty() && System.currentTimeMillis() < deadline) {
            missing.removeIf(rank -> {
                Long neighborBucket = neighborBuckets.get(rank);
                return neighborBucket != null && neighborBucket >= bucket;
            });
            if (!missing.isEmpty()) {
                LockSupport.parkNanos(1_000_000);  // 1ms
            }
        }

        return new WaitOutcome(
            missing.isEmpty() ? WaitResult.ALL_READY :
                missing.size() < neighborRanks.size() ? WaitResult.PARTIAL : WaitResult.TIMEOUT,
            missing,
            System.currentTimeMillis() - (deadline - timeoutMs)
        );
    }
}
```

### DeterministicMath.java

```java
public final class DeterministicMath {
    private DeterministicMath() {}

    // StrictMath for per-platform consistent results
    public static float sqrt(float x) { return (float) StrictMath.sqrt(x); }
    public static float sin(float x)  { return (float) StrictMath.sin(x); }
    public static float cos(float x)  { return (float) StrictMath.cos(x); }

    // Stable force accumulation via binary reduction tree
    public static Vector3f sumForces(List<Vector3f> forces) {
        if (forces.isEmpty()) return new Vector3f();
        if (forces.size() == 1) return new Vector3f(forces.get(0));

        // Sort for consistent order
        var sorted = new ArrayList<>(forces);
        sorted.sort(Comparator.comparingDouble((Vector3f v) -> v.x)
            .thenComparingDouble(v -> v.y)
            .thenComparingDouble(v -> v.z));

        // Binary reduction
        while (sorted.size() > 1) {
            var next = new ArrayList<Vector3f>();
            for (int i = 0; i < sorted.size(); i += 2) {
                var sum = new Vector3f(sorted.get(i));
                if (i + 1 < sorted.size()) sum.add(sorted.get(i + 1));
                next.add(sum);
            }
            sorted = next;
        }
        return sorted.get(0);
    }
}
```

