## SlowStopComponent helper (add to LifecycleCoordinatorTest.java)

  static class SlowStopComponent implements LifecycleComponent {
      private final String name;
      private final CountDownLatch gate;      // test releases to unblock stop
      private final CountDownLatch entered;  // signals test that stop() was called
      private volatile LifecycleState state = LifecycleState.STOPPED;

      SlowStopComponent(String name, CountDownLatch gate, CountDownLatch entered) {
          this.name = name; this.gate = gate; this.entered = entered;
      }

      @Override public String name() { return name; }
      @Override public List<String> dependencies() { return List.of(); }
      @Override public boolean dependenciesAreOrderingOnly() { return false; }
      @Override public LifecycleState getState() { return state; }

      @Override public CompletableFuture<Void> start() {
          state = LifecycleState.RUNNING;
          return CompletableFuture.completedFuture(null);
      }

      @Override public CompletableFuture<Void> stop() {
          return CompletableFuture.runAsync(() -> {
              entered.countDown();
              try { gate.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
              state = LifecycleState.STOPPED;
          });
      }
  }

