public enum SplitAxis { X, Y, Z }

public record SplitPlane(Point3f normal, float distance, SplitAxis axis) {
    // Backward-compatible constructor
    public SplitPlane(Point3f normal, float distance) {
        this(normal, distance, inferAxis(normal));
    }

    private static SplitAxis inferAxis(Point3f normal) {
        if (normal.x > 0.9f) return SplitAxis.X;
        if (normal.y > 0.9f) return SplitAxis.Y;
        return SplitAxis.Z;
    }

    public static SplitPlane forAxis(SplitAxis axis, Point3f centroid) {
        return switch(axis) {
            case X -> new SplitPlane(new Point3f(1,0,0), centroid.x, X);
            case Y -> new SplitPlane(new Point3f(0,1,0), centroid.y, Y);
            case Z -> new SplitPlane(new Point3f(0,0,1), centroid.z, Z);
        };
    }

    public SplitAxis nextAxis() {
        return SplitAxis.values()[(axis.ordinal() + 1) % 3];
    }
}
